Пусть переменная planet равна {
    "name": "Mars",
    "gravity": 0.376
} Тогда запрос strict $planet.name даст "Mars". В отличии от многих языков программирования, JsonPath не поддерживает создание новых переменных или изменение существующих.

$json = CAST(@@{
    "title": "Rocinante",
    "crew": [
        "James Holden",
        "Naomi Nagata",
        "Alex Kamai",
        "Amos Burton"
    ]
}@@ as Json);

SELECT
    JSON_EXISTS($json, "$.title"), -- True
    JSON_EXISTS($json, "$.crew[*]"), -- True
    JSON_EXISTS($json, "$.nonexistent"); -- False, так как JsonPath вернет пустой результат

SELECT
    -- Ошибка JsonPath, вернет False, так как по умолчанию используется FALSE ON ERROR
    JSON_EXISTS($json, "strict $.nonexistent");

SELECT
    -- Ошибка JsonPath, весь YQL запрос завершится ошибкой
    JSON_EXISTS($json, "strict $.nonexistent" ERROR ON ERROR);

$json = CAST(@@{
    "friends": [
        {
            "name": "James Holden",
            "age": 35
        },
        {
            "name": "Naomi Nagata",
            "age": 30
        }
    ]
}@@ as Json);

SELECT
    JSON_VALUE($json, "$.friends[0].age"), -- "35" (тип Utf8?)
    JSON_VALUE($json, "$.friends[0].age" RETURNING Uint64), -- 35 (тип Uint64?)
    JSON_VALUE($json, "$.friends[0].age" RETURNING Utf8); -- пустой Utf8?, так как произошла ошибка. Тип JSON значения Number не соответствует строковому типу Utf8

SELECT
    -- "empty" (тип String?)
    JSON_VALUE(
        $json,
        "$.friends[50].name"
        RETURNING String
        DEFAULT "empty" ON EMPTY
    );

SELECT
    -- 20 (тип Uint64?). Результат выполнения JsonPath пустой, но значение
    -- по умолчанию из секции ON EMPTY не может быть приведено к Uint64.
    -- Поэтому используется значение из ON ERROR
    JSON_VALUE(
        $json,
        "$.friends[50].age"
        RETURNING Uint64
        DEFAULT -1 ON EMPTY
        DEFAULT 20 ON ERROR
    );

$json = CAST(@@{
    "friends": [
        {
            "name": "James Holden",
            "age": 35
        },
        {
            "name": "Naomi Nagata",
            "age": 30
        }
    ]
}@@ as Json);

SELECT
    JSON_QUERY($json, "$.friends[0]"); -- {"name": "James Holden", "age": 35}

SELECT
    JSON_QUERY($json, "$.friends.name" WITH UNCONDITIONAL WRAPPER); -- ["James Holden", "Naomi Nagata"]

SELECT
    JSON_QUERY($json, "$.friends[0]" WITH CONDITIONAL WRAPPER), -- {"name": "James Holden", "age": 35}
    JSON_QUERY($json, "$.friends.name" WITH CONDITIONAL WRAPPER); -- ["James Holden", "Naomi Nagata"]

Цель версионирования языка — контролируемая и безопасная для пользователей эволюция языка, в рамках которой можно: добавлять новые фичи;


менять значения по умолчанию у прагм или выполнять другие не обратно совместимые изменения;


удалять устаревшие фичи. Стартовая версия языка — 2025.01. Раз в год выпускается новая версия языка, именуемая как YEAR.X, например 2025.01. Другие версии в тот же год будут увеличивать младший номер версии (YEAR.02 и т. п.). Для каждой версии вида YEAR.X гарантируется ее поддержка в течение трех лет с сохранением семантики и багфиксами. При выходе версии YEAR+2.1 выдается предупреждение для всех версий вида YEAR.X о том, что они скоро перестанут поддерживаться. При выходе версии YEAR+3.1 выдается предупреждение для всех версий вида YEAR.X о том, что они не поддерживаются и выполнение запросов не гарантируется. При указании версии YEAR.X большей, чем доступно в некотором сервисе/библиотеке/инструменте на текущий момент, выдается ошибка запроса. При релизе каждой версии в changelog-е в документации указываются изменения, вошедшие в эту версию и рекомендации по миграции.

