$input = "some/input/path";
$output = "destination/path";

-- Фильтруем пользовательские атрибуы, начинающиеся с подчеркивания, и исключаем некоторые системные YQL атрибуты
$user_attr = ($attr) -> {
    RETURN ListFilter(
        Yson::ConvertToStringList($attr.user_attribute_keys),
        ($name) -> {
            RETURN StartsWith($name, "_") AND $name NOT IN ["_yql_op_id", "_yql_row_spec", "_yql_runner"];
        }
    );
};

-- Добавляем префикс // к пути
$yt_path = ($path) -> {
    RETURN IF(StartsWith($path, "//"), $path, "//" || $path);
};

-- Создаём список атрибутов для копирования
$attribute_keys = (
    SELECT String::JoinFromList($user_attr(Attributes), ";")
    FROM Folder(Substring($input, NULL, RFind($input, "/")), "user_attribute_keys")
    WHERE $yt_path(Path) == $yt_path($input)
);

-- Читаем пользовательские атрибуты
$attributes = (
    SELECT CAST(Yson::SerializePretty(Attributes) AS String) as attrs
    FROM Folder(Substring($input, NULL, RFind($input, "/")), $attribute_keys)
    WHERE $yt_path(Path) == $yt_path($input)
);

-- Форсируем скалярный контекст
$attributes = EvaluateExpr($attributes);

INSERT INTO $output WITH (TRUNCATE, USER_ATTRS=$attributes)
SELECT *
FROM (
    SELECT *
    FROM $input
    LIMIT 5
)

Для этого потребуются предустановленные функции сериализации и стандартная функция TableRow() для обращения ко всей строке: USE <cluster-name>;
SELECT Yson::SerializeJson(Yson::From(TableRow()))
FROM `home/yql/tutorial/users`;

При работе с JSON'ом / YSON'ом стоит помнить: Несериализованное поле этих форматов нельзя вывести в браузере или сохранить в таблицу — возникает ошибка вида  Expected persistable data, but got: List<Struct<'column0':Resource<'Yson.Node'>>>;
Не стоит преобразовывать в словарь, если нужно получить значение только по одному ключу. -- Тип my_column — Yson

SELECT Yson::Serialize(my_json_column.myKey) AS my_column
FROM my_table; Если требуется конкретный тип данных, то можно воспользоваться функцией Yson::ConvertTo...: -- Тип my_column — String

SELECT Yson::ConvertToString(my_json_column.myKey) AS my_column
FROM my_table; Если исходный тип колонки строка, то можно воспользоваться функцией Yson::Parse...: SELECT Yson::Serialize(Yson::Parse(my_yson_column)) AS my_yson;

-- В результате получается Yson, при работе с которым Yson::Parse подставляется автоматически

SELECT Yson::Serialize(my_yson.myKey) AS my_key_value; Если требуется список из всех значений по ключу, то можно воспользоваться функцией ListMap: SELECT
    ListMap(
        Yson::ConvertToList(my_yson_column),
        ($x) -> { RETURN Yson::Serialize($x.foo) }
    );

-- Результат выполнения — список строк Пример получения элемента списка: SELECT Yson::ConvertToString(Yson::ConvertToList(my_yson_column)[0].foo);

-- Результат выполнения — поле конкретного элемента списка

Кластер YTsaurus — группа инстансов, расположенных в контейнерах на физических хостах и функционирующих как единое целое.
Исходя из решаемых задач, кластеры могут делиться на: вычислительные кластеры для массивной параллельной обработки больших данных при помощи MapReduce операций;
кластеры для динамических таблиц (key-value хранилище);
геораспределённые кластеры, выполняющие функции координации. Вычислительный кластер YTsaurus способен: хранить эксабайты данных;
использовать HDD, SSD и RAM для хранения данных;
обрабатывать данные на сотнях тысяч Hyper Threading ядер;
решать задачи машинного обучения на тысячах графических процессоров (GPU);
хранить и обрабатывать данные десятков тысяч пользователей.

В архитектуре YTsaurus можно выделить три слоя: распределённая файловая система и хранилище метаинформации — Кипарис;
планировщик для распределённых вычислений с поддержкой модели MapReduce;
высокоуровневые вычислительные движки: YQL, CHYT, SPYT.

Кипарис — отказоустойчивое древовидное хранилище. Возможности Кипариса можно описать следующим образом: древовидное пространство имён, узлами которого являются директории, таблицы и файлы;
прозрачное шардирование больших табличных данных на чанки, которое позволяет работать с таблицей, как единой сущностью, не думая о деталях её хранения;
поддержка колоночного и строчного механизмов хранения табличных данных;
поддержка сжатого хранения с использованием различных кодеков — например, lz4 и zstd с настраиваемым уровнем сжатия;
поддержка erasure-кодирования с использованием разнообразных стратегий подсчета контрольных сумм, обладающих разными параметрами избыточности и допустимых видов потерь;
выразительная схематизация данных с поддержкой иерархических типов и признаков сортированности данных;
фоновые репликация и починка erasure-данных, не требующие ручных действий;
транзакционная семантика с поддержкой вложенных транзакций и блокировок уровней snapshot/shared/exclusive;
транзакции, которые могут затрагивать много объектов Кипариса и длиться неограниченно долго;
гибкая система разделения и учёта дискового пространства;
гибкая система разграничения прав доступа к данным, включая доступ к колонкам таблиц. Основа Кипариса — реплицированный и горизонтально-масштабируемый мастер-сервер, который хранит метаинформацию об устройстве дерева Кипариса, а также о составе и местоположении реплик чанков всех таблиц на кластере. Мастер-серверы представляют собой Replicated State Machine, реализованную поверх технологии Hydra — in-house версии алгоритма консенсуса, схожей с Raft.
Кипарис реализует отказоустойчивый эластичный слой хранения данных. Помимо хранения Кипарис может выступать сервисом координации (lock service), по аналогии с Apache Zookeeper. С пользовательской точки зрения Кипарис похож на дерево файловой системы в Linux. Самый простой способ работать с Кипарисом — использовать веб-интерфейс.

Динамические таблицы — это вид таблиц в YTsaurus, реализующих интерфейс точечного чтения и записи данных по ключу, поддерживающих транзакции и собственный диалект SQL. Ключевые особенности динамических таблиц: хранение данных в модели MVCC, позволяющее читать значения по ключу и таймстемпу;
масштабируемость: динамическая таблица делится на таблеты (шарды по диапазонам ключей), которые обслуживаются отдельными узлами кластера;
транзакционность: динамические таблицы — это OLTP-хранилища, позволяющие модифицировать в одной транзакции множество строк из разных таблетов различных таблиц;
отказоустойчивость: выход отдельного узла кластера, обслуживающего таблет, приводит к тому, что данный таблет переезжает на другой узел кластера без потери данных;
изоляция: инстансы, обслуживающие таблеты, группируются в бандлы, находящиеся на отдельных серверах, за счет чего обеспечивается изоляция нагрузки;
проверка конфликтов на уровне отдельных ключей или даже отдельных значений;
возможность ответа из RAM для горячих данных;
удаление данных по TTL;
встроенный SQL-like язык для сканирующих аналитических запросов. Помимо динамических таблиц с интерфейсом k-v storage в системе есть поддержка динамических таблиц, реализующих абстракцию очереди сообщений — а именно топика и потока. Указанные очереди также можно считать таблицами, потому что они состоят из строк и обладают собственной схемой. В одной транзакции можно одновременно изменять строки в k-v динамической таблице, а также в очереди. Это позволяет строить потоковую обработку данных поверх динамических таблиц YTsaurus с exactly-once семантикой.

В основе вычислительной архитектуры YTsaurus лежит модель распределённых вычислений MapReduce. Операция Map обрабатывает входные данные, разделённые на части между узлами кластера, без обмена данными между узлами. Операция Reduce выполняет группировку данных с разных узлов кластера.
Модель позволяет обрабатывать большие объемы данных с высокой надежностью и автоматически перезапускать часть вычислений в случае недоступности отдельных узлов кластера. MapReduce в YTsaurus обладает следующими отличительными чертами: богатая модель базовых операций: классический MapReduce (с разными стратегиями shuffle и поддержкой многофазного партиционирования), Map, Erase, Sort, и разнообразные расширения модели с учётом сортированности входных данных;
горизонтальная масштабируемость вычислительных операций: операции дробятся на джобы, которые работают на отдельных узлах кластера;
поддержка до сотен тысяч джобов в одной операции;
гибкая модель иерархических вычислительных пулов с мгновенными и интегральными гарантиями, а также fair_share распределением недоутилизированных ресурсов между потребителями без гарантий;
векторная модель ресурсов, позволяющая заказывать различные вычислительные ресурсы (CPU, RAM, GPU) в разных пропорциях;
запуск джобов на вычислительных узлах в контейнерах, изолированных друг от друга по CPU, RAM, файловой системе и process namespace с использованием механизма контейнеризации Porto;
масштабирующийся планировщик, способный обслуживать кластеры с миллионом одновременно исполняемых задач;
сохранение практически всего прогресса вычислений при обновлениях или выходе отдельных узлов планировщика из строя. Следует отметить возможность запускать не только MapReduce-джобы, но и произвольный код. В терминологии YTsaurus запуск произвольного кода достигается с помощью ванильных (Vanilla) операций.

YQL — универсальный, декларативный, основанный на SQL язык запросов к системам хранения и обработки данных, а также инфраструктура для их выполнения. К преимуществам YQL можно отнести: мощный графовый движок исполнения, который строит MapReduce-pipelines из сотен узлов и может адаптивно перестраиваться по ходу вычисления;
возможность построения сложного конвейера обработки данных на SQL с сохранением подзапросов в переменные в виде цепочек зависимых запросов и транзакций;
предсказуемое параллельное исполнение запросов произвольной сложности;
эффективная реализация join-ов, подзапросов и оконных функций без ограничений на их топологию и вложенность;
богатая библиотека функций;
поддержка пользовательских функций на C++, Python и JavaScript;
поддержка функций использования моделей машинного обучения с применением CatBoost и TensorFlow;
автоматическое исполнение небольших частей запросов на заранее подготовленных вычислительных инстансах в обход MapReduce-операций для уменьшения времени выполнения.

ClickHouse over YTsaurus (CHYT) — это технология, которая позволяет поднять кластер из серверов ClickHouse непосредственно на вычислительных узлах YTsaurus.
ClickHouse поднимается внутри Vanilla-операции и работает с данными, которые находятся в YTsaurus. Кластер YTsaurus выступает compute-облаком по отношению к запущенным в нём кластерам CHYT.
Технология позволяет разным пользователям запустить на одном кластере YTsaurus несколько кластеров CHYT, которые будут абсолютно изолированы друг от друга, и решить тем самым задачу разделения ресурсов в облачном стиле. В экосистеме YTsaurus CHYT отвечает: за быстрые аналитические запросы поверх статических таблиц в YTsaurus со временем ответа менее секунды;
переиспользование уже имеющихся данных в кластере YTsaurus без необходимости копировать их в отдельный кластер ClickHouse;
возможность интеграции через ODBC и JDBC-драйверы ClickHouse, например, со сторонними системами визуализации такими как: Tableau, Qlik, Power BI, Oracle Bi и DataLens. Интеграция произведена на довольно низком уровне. Это позволяет получить максимум возможностей как от YTsaurus, так от ClickHouse. В данной интеграции реализована: поддержка чтения как статических, так и динамических таблиц;
частичная поддержка транзакционной модели YTsaurus;
поддержка распределённых вставок;
CPU-efficient-преобразование колоночных данных из внутреннего формата YTsaurus в in-memory представление ClickHouse;
агрессивное кэширование данных, позволяющее в ряде случаев читать данные для исполнения запросов исключительно из памяти инстансов.

В системе YTsaurus реализован единый веб-интерфейс для пользователей и администраторов. С его помощью можно: перемещаться по Кипарису и просматривать данные;
производить операции с таблицами, папками и файлами;
запускать и просматривать MapReduce-вычисления;
запускать и просматривать историю SQL-запросов во всех вычислительных движках — в YQL, CHYT, SQL динамических таблиц;
администрировать систему:

следить за состоянием компонент кластера;
создавать, удалять пользователей и группы;
управлять квотами;
просматривать настройки контроля доступа;
просматривать версии компонент кластера и многое другое.

У разных типов объектов имеется свой набор системных атрибутов, специфичных для данного типа. Например, у любого объекта есть атрибут id, у таблиц есть атрибуты compression_codec и compressed_data_size. Подробнее про атрибуты, присущие всем объектам, можно почитать в разделе Объекты. Системные атрибуты бывают изменяемыми (может изменять пользователь), например compression_codec, и неизменяемыми, например compressed_data_size. При попытке установить неизменяемый атрибут система вернет ошибку. Попытка удаления системного атрибута также приведет к ошибке. Некоторые атрибуты являются наследуемыми: такие атрибуты можно устанавливать на директориях (map-нодах), где они являются nullable, то есть могут не иметь (и не имеют по умолчанию) никакого значения. Если при создании нового объекта не указано значение наследуемого атрибута, данный атрибут получает значение ближайшего узла-предка или значение по умолчанию, если ни у одного предка вплоть до корня атрибут не установлен. Для разных типов объектов наследуются разные множества атрибутов. Следующие атрибуты наследуются таблицами, файлами и журналами: chunk_merger_mode;
compression_codec;
enable_striped_erasure;
erasure_codec;
hunk_media;
hunk_primary_medium;
media;
primary_medium;
replication_factor;
vital. В дополнение к перечисленным, следующие атрибуты наследуются только таблицами: atomicity;
hunk_erasure_codec;
commit_ordering;
in_memory_mode;
optimize_for;
profiling_mode;
profiling_tag;
tablet_cell_bundle. Реплицированные Хаосные таблицы наследуют следующие атрибуты: chaos_cell_bundle. Также системные атрибуты могут быть непрозрачными (вычисляемыми, opaque), то есть их значение будет доступно только при явном запросе командой get, но не будет доступно (а точнее, значение атрибута будет равно entity) при запросе всех атрибутов. Чаще всего непрозрачными объявляются атрибуты, имеющие большое значение (в смысле объема данных), либо вычисление которых требует значительного времени. То есть, если данные в атрибуте составляют более сотни килобайт, имеет смысл делать их непрозрачными. В таком случае при запросе всех атрибутов, они не будут возвращаться, и чтение всех атрибутов будет быстрее. Если требуется получить эти значения, нужно явно их запросить. Примером непрозрачного атрибута будет список всех чанков таблицы (атрибут chunk_ids) или суммарное использование ресурсов по поддереву Кипариса (атрибут recursive_resource_usage). Ниже представлен список атрибутов объектов системы YTsaurus: атрибуты любого объекта;
атрибуты узлов Кипариса;
атрибуты статических таблиц;
атрибуты динамических таблиц;
атрибуты файлов;
атрибуты compression_codec и erasure_codec для таблиц и файлов;
атрибуты транзакций;
атрибуты ссылок;
атрибуты аккаунтов;
атрибуты медиумов.

Reduce с внешними таблицами — это модификация операции Reduce, в которой часть входных таблиц помечены как внешние (foreign) таблицы и выполняют роль справочников, данные которых добавляются к потоку данных из «обычных» (первичных, primary) таблиц. Для внешних таблиц используется специальный набор ключевых колонок join_by, который должен быть префиксом набора колонок reduce_by. Возможна ситуация, когда записи с одним и тем же join_by ключом, но разными reduce_by ключами попали в разные джобы — в таком случае соответствующие записи из внешних таблиц будут поданы на вход всем джобам, а значит, обработаны более одного раза. Возможна обратная ситуация, если таблица справочник может содержать больше различных комбинаций значений, чем основная таблица. Если записи из внешней таблицы не соответствует ни одна запись из основных, то такая запись может не попасть ни в один джоб. Внимание
Поскольку чанки внешних таблиц читаются много раз, категорически не рекомендуется использовать для них erasure-кодирование. Напротив, если внешняя таблица маленькая, стоит выставить для неё повышенный коэффициент репликации. Использование erasure для внешней таблицы может привести к перекосу нагрузки на чтение по узлам кластера и деградации производительности всего кластера. Важным отличием Reduce с внешними таблицами от обычной Reduce-операции является гранулярность вызова пользовательского скрипта в python-wrapper и C++ wrapper. В отличие от обычной Reduce-операции, пользовательский скрипт (метод IReducer::Do в С++ API и функция-обработчик в python) вызывается на каждый join_by ключ, а не reduce_by ключ.
Требования к спецификации для Reduce с внешними таблицами: должна быть указана хотя бы одна первичная таблица (отсутствует атрибут foreign);
должна быть указана хотя бы одна внешняя таблица при помощи атрибута <foreign=%true>;
должно быть указано значение join_by;
join_by должен быть префиксом или совпадать с reduce_by;
нельзя использовать join_by без внешних таблиц и внешние таблицы без join_by;
нельзя устанавливать атрибут teleport на внешнюю таблицу;
нельзя задавать множественные диапазоны (ranges) для внешней таблицы, но одна и та же внешняя таблица может быть указана несколько раз с разными диапазонами. Также для операции Reduce с внешними таблицами доступна опция consider_only_primary_size (по умолчанию %false), при включении которой при разбивке джобов будет учитываться только объем данных в первичных (primary) таблицах. Выставление опции enable_key_guarantee=%false в Reduce с внешними таблицами имеет особую семантику: Отключается гарантия на то, что все записи с одинаковым ключом из первичной таблицы попадут в один джоб. При этом сохраняется гарантия того, что если в джоб попала запись из первичной таблицы с некоторым ключом, то все записи с таким же ключом из всех внешних таблиц попадут в тот же джоб.
Список ключей пользователь должен передавать в join_by, указывать reduce_by запрещено. Рекомендуется использовать операцию Reduce с опцией enable_key_guarantee=%false.

{
  data_weight_per_job = 1000000;
  reduce_by = ["key"];
  sort_by = ["key"; "subkey" ];
  input_table_paths = [ "//tmp/input_table" ];
  output_table_paths = [ "//tmp/unsorted_output_table"; <sorted_by = ["key"]> "//tmp/sorted_output_table" ];
  reducer = {
    command = "python my_reducer.py"
    file_paths = [ "//tmp/my_reducer.py" ];
  };
  job_io = {
    table_writer = {
      max_row_weight = 10000000;
    }
  }
}

Планировщик оперирует следующими ресурсами: cpu — 1 CPU соответствует одному HyperThreading ядру на узле кластера. По умолчанию все пользовательские джобы заказывают при запуске одно ядро. Если джобы многопоточные, то можно увеличить количество заказанных ядер в настройках операции. В противном случае джобы процессов будут ограничены (throttling) таким образом, чтобы количество реально потребляемого процессорного времени соответствовало одному ядру;
memory — ресурс для контроля потребления оперативной памяти на узле кластера в байтах;
user_slots — ресурс для контроля числа джобов на узле кластера. Каждый джоб пользовательских операций всегда потребляют ровно один user_slot;
network — ресурс для контроля потребления внутренней сети кластера операциями, активно использующими сеть. Например, сортировки. У единицы ресурса нет физического аналога, а автоматически выставляемые планировщиком значения для операций сортировки подобраны таким образом, чтобы джобы, запущенные на одном и том же узле кластера, не перегружали сетевой канал. Для каждого пула и операции существует понятие доминантного ресурса. Доминантным ресурсом среди запрашиваемых ресурсов операции или пула считается тот вид ресурса, который имеет наибольшую долю относительно общего объёма соответствующего ресурса всего кластера. Например: есть операция, для выполнения которой требуется 1 000 cpu и 2 TiB memory. При этом во всём кластере 50 000 cpu и 180 TiB memory. Тогда можно оценить, что 1 000 cpu составляет 0.02 (2%) от общего числа cpu в кластере, а 2 TiB составляет 0.011 (1.1%) от общего объёма memory кластера. Доля cpu больше доли memory, поэтому для конкретной операции доминантным ресурсом является cpu.

Планировщик YTsaurus хранит в памяти несколько деревьев пулов. Каждое дерево состоит из операций и вычислительных пулов. Узлами дерева являются вычислительные пулы, а операции — листьями. Каждая операция может принадлежать одному или нескольким деревьям. Логически можно рассматривать каждое дерево как отдельный вычислительный кластер — каждому дереву принадлежит некоторое количество вычислительных узлов кластера, при этом узел кластера может принадлежать только одному дереву. Деревья пулов хранятся в Кипарисе и настраиваются администратором системы YTsaurus. Дерево пулов представляет из себя узел scheduler_pool_tree на первом уровне директории //sys/pool_trees в Кипарисе. Описание пулов для дерева <tree_id> представляет собой набор вложенных scheduler_pool, находящихся в узле //sys/pool_trees/<tree_id>. Характеристики пулов описываются в атрибутах соответствующих узлов. Деревья, в которые попадет операция при запуске, определяются параметром pool_trees в настройках операции. Если данный параметр не указан, то будет использовано одно дерево по умолчанию default_pool_tree. Для каждого из перечисленных деревьев можно указать пул из этого дерева, в котором нужно запустить операцию (опция scheduling_options_per_pool_tree). У каждого дерева пулов существует атрибут default_parent_pool, указывающий на пул по умолчанию. Данный пул используется следующим образом: если в настройках операции для дерева или для всех деревьев пул указан не был, в дереве будет создан временный эфемерный пул с именем пользователя в YTsaurus, запустившего операцию. Пулы образуют иерархию //sys/pool_trees/<tree_id>/<default_parent_pool>/<username>, в конечном узле которой и будет запущена операция. Пример настройки для запуска операции в двух деревьях с указанием пула в одном из них: pool_trees = [default; cloud];
scheduling_options_per_pool_tree = {
    default = {
        pool = cool_pool;
    }
}

Образ корневой файловой системы содержит самодостаточный дистрибутив операционной системы, приложения и библиотеки для запуска пользовательской команды в изолированном контейнере. В зависимости от настройки кластера (опция exec_node/slot_manager/job_environment/type в файле конфигурации exec-нод) среда исполнения поддерживает различные форматы и источники образов: simple — не поддерживает изоляцию;
cri — Docker Image;
porto — Porto Layers, Docker Image из Internal Docker Registry.

Docker Layer — фрагмент данных образа корневой файловой системы;
Docker Image — образ корневой файловой системы, состоящий из метаданных и упорядоченного множества слоёв;
Docker Registry — сервер, хранящий и распространяющий данные и метаданные Docker образов;
Internal Docker Registry — docker registry, хранящий образы непосредственно в Кипарисе. Docker образ адресуется по имени в формате [REGISTRY/]IMAGE[:TAG|@DIGEST], где REGISTRY это FQDN[:PORT] сервера Docker Registry. Registry FQDN должен иметь хотя бы одну "." или PORT. TAG по умолчанию latest. Подробнее Docker образ без указания REGISTRY считается образом из Internal Docker Registry, где IMAGE соответствует пути //IMAGE в Кипарисе до директории с метаданными образа. Internal Docker Registry доступен по стандартному протоколу docker registry для загрузки образов пользователями используя инструменты docker или совместимые с ними. Но не поддерживает адресацию docker image с указанием DIGEST. Для использования docker образов из Docker Hub нужно указать их полное имя в формате docker.io/[library/]IMAGE[:TAG|@DIGEST]. Запуск с использованием docker образов из внешних docker registry требует наличия сетевого доступа до него от exec-нод кластера. Доступ к internal docker registry происходит внутри кластера. Каждая exec-нода при запуске джоба скачивает образ себе в локальный кэш, следовательно крупный кластер может генерировать существенную нагрузку на docker registry.

Porto слой — фрагмент образа корневой файловой системы для Porto;
Образ RootFS — образ корневой файловой системы;
Базовый слой (базовый образ) — самодостаточный образ, в котором лежит основная часть окружения (/bin/bash, libc6, etc); фактически выбирая базовый слой, вы фиксируете версию Ubuntu (Precise, Trusty, Xenial, Bionic и т.д.), в которой будет работать ваш код;
Дельта слой — слой, который является дополнением к базовому образу и обычно содержит дополнительные библиотеки или бинарные артефакты.

Все зависимости ставятся в SPYT автоматически, поэтому  значение для scope – Provided. Они будут использоваться только для компиляции и не будут включены в .jar для запуска. Все допустимые значения для spytVersion можно найти здесь под тегами spyt/* или spyt-spark/*. Совместимые версии Apache Spark указаны в таблице совместимости. val sparkVersion = "3.5.4"
val spytVersion = "2.7.1"

libraryDependencies ++= Seq(
    // зависимости от Spark
    "org.apache.spark" %% "spark-core" % sparkVersion % Provided,
    "org.apache.spark" %% "spark-sql" % sparkVersion % Provided,
    // библиотека SPYT
    "tech.ytsaurus" %% "spark-yt-data-source" % spytVersion % Provided
)

В случае использования запуска задач с использованием планировщика YTsaurus, для создания SparkSession нужно воспользоваться стандартными рекомендациями Spark: import org.apache.spark.SparkConf
import org.apache.spark.sql.SparkSession

object MySparkApplication {

    def main(args: Array[String]): Unit = {
        val conf = new SparkConf()
        val spark = SparkSession.builder.config(conf).getOrCreate()

        try {
            // Application code
        } finally {
            spark.stop()
        }
    }
} В этом случае запуск выполняется при помощи команды spark-submit: $ spark-submit \
  --master ytsaurus://${YT_PROXY} \
  --deploy-mode cluster \
  --class tech.ytsaurus.spyt.examples.GroupingExample \
  yt:///home/spark/examples/scala-examples-assembly-0.1.jar

Чтобы получить экзекьюторы, драйвер делает запрос планировщику (scheduler) ресурсов. Для создания контейнеров нужного размера необходимо знать, какие узлы кластера существуют и сколько в них ресурсов. Обычно функции создания контейнеров выполняет YARN или Mesos, в системе YTsaurus существует свой планировщик ресурсов. В текущей реализации есть два варианта запуска Spark задач: с использованием планировщика YTsaurus, либо с использованием внутреннего Spark Standalone кластера, который разворачивается внутри Vanilla операции. Spark Standalone состоит из мастера и воркеров. Каждый воркер знает, сколько ресурсов можно занять на узле кластера где запущен воркер, и умеет предоставлять ресурсы по запросу. Мастер координирует работу: он получает запросы от драйвера и решает, на каких воркерах создать экзекьюторы.  Для запроса ресурса у мастера драйверу необходимо знать хост и порт мастера. При запуске в Vanilla-операции Spark-мастер попадает на случайный узел кластера YTsaurus и открывает там порт в диапазоне от 27000 до 27200. После этого Spark-мастер прописывает свой хост и порт в Кипарисе в специальную директорию discovery-path. В драйвере существует код, который обращается к Кипарису, узнаёт хост и порт Spark-мастера и обращается к нему.  Кластер планировщика запускается командой spark-launch-yt. В аргументах команды необходимо указать: сколько ресурсов будет у каждого воркера (ядра / память);
число воркеров;
какую директорию Кипариса использовать как discovery-path. Внимание
Разница между приложением и кластером:

Драйвер и экзекьюторы образуют Spark-приложение. Spark приложение решает прикладную задачу пользователя, например: сделать join двух таблиц, записать результат.
Мастер и воркеры образуют Spark-кластер. Spark-кластер отвечает на запросы приложений по запуску новых экзекьюторов.

Данный способ подходит при интенсивном использовании кластера. В данном режиме YTsaurus выделяет ресурсы под внутренний Standalone Spark кластер, который занимается выполнением расчетов. Для запуска в этом режиме необходимо использовать обёртки над стандартными командами Spark spark-submit-yt и spark-shell-yt, входящими в состав пакета ytsaurus-spyt. Этот режим рекомендуется использовать в следующих случаях: Запуск задач с высокой периодичностью (более 1 раза в час). Эффективность достигается за счет того, что время запуска задачи в standalone кластере существенно меньше, чем время запуска операции в YTsaurus.
Ad-hoc аналитика в Jupyter-ноутбуках.
Ad-hoc аналитика с использованием Query tracker и livy. Для запуска внутреннего standalone Spark кластера необходимо выполнить следующие шаги: Выберите пользователя, от имени которого необходимо запустить кластер. Код, который регулярно запускается на Spark, нужно загрузить в систему YTsaurus. У пользователя, от имени которого запущен кластер, должны быть права на чтение кода.


Создайте директорию для служебных данных Spark, например my_discovery_path. Пользователь, от имени которого запущен кластер, должен иметь права на запись в директорию. Пользователи, которые будут запускать джобы на Spark, должны иметь права на чтение директории.


Запустите кластер:


        $ spark-launch-yt \
--proxy <cluster-name> \
--pool  my_pool \
--discovery-path my_discovery_path \
--worker-cores 16 \
--worker-num 5 \
--worker-memory 64G












Опции:

spark-launch-yt — запуск в Vanilla-операции YTsaurus с клиентского хоста;
--proxy — имя кластера;
--pool — вычислительный пул YTsaurus;
--spyt-version — директория для служебных данных Spark;
--worker-cores — количество ядер у воркера;
--worker-num — количество воркеров;
--worker-memory — количество памяти у каждого воркера;
--spark-cluster-version — версия кластера (опционально).



Запустите тестовый джоб на кластере:


        $ spark-submit-yt \
--proxy <cluster-name> \
--discovery-path my_discovery_path \
--deploy-mode cluster \
yt:///sys/spark/examples/smoke_test.py












Опции:

spark-submit-yt — обертка над spark-submit, позволяет определить адрес мастера Spark из Vanilla-операции. Поиск производится по аргументам: proxy, id, discovery-path;
--proxy — имя кластера;
--discovery-path — директория для служебных данных Spark;
--deploy-mode (cluster или client) — режим запуска кластера;
--spyt-version — версия SPYT (опционально);
адрес файла с кодом в YTsaurus.

$value = "xaaxaaXaa";

$match = Hyperscan::Match("a.*");
$grep = Hyperscan::Grep("axa");
$insensitive_grep = Hyperscan::Grep("(?i)axaa$");
$multi_match = Hyperscan::MultiMatch(@@a.*
.*a.*
.*a
.*axa.*@@);

$capture = Hyperscan::Capture(".*a{2}.*");
$capture_many = Hyperscan::Capture(".*x(a+).*");
$replace = Hyperscan::Replace("xa");

SELECT
    $match($value) AS match,                        -- false
    $grep($value) AS grep,                          -- true
    $insensitive_grep($value) AS insensitive_grep,  -- true
    $multi_match($value) AS multi_match,            -- (false, true, true, true)
    $multi_match($value).0 AS some_multi_match,     -- false
    $capture($value) AS capture,                    -- "xaa"
    $capture_many($value) AS capture_many,          -- "xa"
    $replace($value, "b") AS replace                -- "babaXaa"
;

В модуле DateTime существует два внутренних формата представления: Resource<TM> для базовых типов дат и Resource<TM64> для расширенных. Resource<TM> и Resource<TM64> хранят следующие компоненты дат: Year (для Resource<TM> 12 бит, беззнаковый; для Resource<TM64> 19 бит, знаковый);
Month (4 бита);
Day (5 бит);
Hour (5 бит);
Minute (6 бит);
Second (6 бит);
Microsecond (20 бит);
TimezoneId (16 бит);
DayOfYear (9 бит) — день от начала года;
WeekOfYear (6 бит) — неделя от начала года, 1 января всегда относится к первой неделе;
WeekOfYearIso8601 (6 бит) — неделя года согласно ISO 8601 (первой неделей считается та, в которой 4 января);
DayOfWeek (3 бита) — день недели. Если таймзона не GMT, то в компонентах хранится локальное время в соответствующей таймзоне.

DateTime::Format(String, alwaysWriteFractionalSeconds:Bool?) -> (Resource<TM64>{Flags:AutoMap}) -> String Для строки форматирования реализовано множество спецификаторов: %% - символ %;
%Y - год 1-6 цифр и знак, для дат до н.э.;
%m - месяц 2 цифры;
%d - день 2 цифры;
%H - час 2 цифры;
%M - минуты 2 цифры;
%S - секунды 2 цифры или XX.XXXXXX в случае непустых микросекунд (и только если флаг alwaysWriteFractionalSeconds не выставлен в True);
%z - +hhmm or -hhmm;
%Z - IANA имя таймзоны;
%b - короткое трехбуквенное английское название месяца (Jan);
%B - полное английское название месяца (January). Все остальные символы строки форматирования переносятся без изменений.

$format = DateTime::Format("%Y-%m-%d %H:%M:%S %Z");

SELECT
    $format(DateTime::Split(TzDatetime("2019-01-01T01:02:03,Europe/Moscow")));
      -- "2019-01-01 01:02:03 Europe/Moscow"

DateTime::Parse(String) -> (String{Flags:AutoMap}) -> Resource<TM>?
DateTime::Parse64(String) -> (String{Flags:AutoMap}) -> Resource<TM64>? Реализованные спецификаторы: %% - символ %;
%Y - год 4 цифры - при использовании Parse, или 1-6 цифр и знак для дат до н.э. - при использовани Parse64;
%m - месяц 2 цифры;
%d - день 2 цифры;
%H - час 2 цифры;
%M - минуты 2 цифры;
%S - секунды, может принимать и микросекунды в форматах от XX до XX.XXXXXX;
%Z - IANA имя таймзоны (GMT);
%b - короткое трехбуквенное регистронезависимое английское название месяца (Jan);
%B - полное регистронезависимое английское название месяца (January).

$parse1 = DateTime::Parse("%H:%M:%S");
$parse2 = DateTime::Parse("%S");
$parse3 = DateTime::Parse("%m/%d/%Y");
$parse4 = DateTime::Parse("%Z");
$parse5 = DateTime::Parse64("%m/%d/%Y");

SELECT
    DateTime::MakeDatetime($parse1("01:02:03")), -- 1970-01-01T01:02:03Z
    DateTime::MakeTimestamp($parse2("12.3456")), -- 1970-01-01T00:00:12.345600Z
    DateTime::MakeTimestamp($parse3("02/30/2000")), -- NULL (Feb 30)
    DateTime::MakeTimestamp($parse4("Canada/Central")), -- 1970-01-01T06:00:00Z (конвертация в UTC)
    DateTime::MakeTimestamp64($parse5("02/10/1931")), -- 1931-02-10T00:00:00Z (конвертация в UTC)

CAST в Date или TzDate дает такую дату в таймзоне GMT, в которую происходит полночь по локальному времени (например, для московского времени 2019-10-22 00:00:00, будет возвращена дата 2019-10-21). Для получения даты в локальной таймзоне можно использовать DateTime::Format. $x = Datetime("2019-10-21T21:00:00Z");
select
    AddTimezone($x, "Europe/Moscow"), -- 2019-10-22T00:00:00,Europe/Moscow
    cast($x as TzDate), -- 2019-10-21,GMT
    cast(AddTimezone($x, "Europe/Moscow") as TzDate), -- 2019-10-21,Europe/Moscow
    cast(AddTimezone($x, "Europe/Moscow") as Date), -- 2019-10-21
  DateTime::Format("%Y-%m-%d %Z")(AddTimezone($x, "Europe/Moscow")), -- 2019-10-22 Europe/Moscow Стоит отметить, что некоторые значения в типaх TzDatetime и TzTimestamp, имеющие положительное смещение таймзоны, не могут быть преобразованы в тип TzDate. Рассмотрим следующий пример: SELECT CAST(TzDatetime("1970-01-01T23:59:59,Europe/Moscow") as TzDate);
/* Fatal: Timestamp 1970-01-01T23:59:59.000000,Europe/Moscow cannot be casted to TzDate */ Не существует такого значения, начиная с Unix epoch, которым можно представить полночь 01.01.1970 для московского времени. В результате, такое преобразование считается невозможным и генерирует ошибку времени выполнения. В то же время, значения, имеющие отрицательное смещение таймзоны, возвращают корректный результат: SELECT CAST(TzDatetime("1970-01-01T23:59:59,America/Los_Angeles") as TzDate);
/* 1970-01-01,America/Los_Angeles */

$value = "xaaxaaxaa";
$match = Pire::Match("a.*");
$grep = Pire::Grep("axa");
$insensitive_grep = Pire::Grep("(?i)axa");
$multi_match = Pire::MultiMatch(@@a.*
.*a.*
.*a
.*axa.*@@);
$capture = Pire::Capture(".*x(a).*");
$capture_many = Pire::Capture(".*x(a+).*");
$replace = Pire::Replace(".*x(a).*");

SELECT
  $match($value) AS match,                        -- false
  $grep($value) AS grep,                          -- true
  $insensitive_grep($value) AS insensitive_grep,  -- true
  $multi_match($value) AS multi_match,            -- (false, true, true, true)
  $multi_match($value).0 AS some_multi_match,     -- false
  $capture($value) AS capture,                    -- "a"
  $capture_many($value) AS capture_many,          -- "aa"
  $replace($value, "b") AS replace;               -- "xaaxaaxba"

$value = "xaaxaaxaa";
$options = Re2::Options(false AS CaseSensitive);
$match = Re2::Match("[ax]+\\d");
$grep = Re2::Grep("a.*");
$capture = Re2::Capture(".*(?P<foo>xa?)(a{2,}).*");
$replace = Re2::Replace("x(a+)x");
$count = Re2::Count("a", $options);

SELECT
  $match($value) AS match,                -- false
  $grep($value) AS grep,                  -- true
  $capture($value) AS capture,            -- (_0: 'xaaxaaxaa', _1: 'aa', foo: 'x')
  $capture($value)._1 AS capture_member,  -- "aa"
  $replace($value, "b\\1z") AS replace,   -- "baazaaxaa"
  $count($value) AS count;                -- 6

$value = "Foo bar FOO"u;
