    public static void main(String[] args) {
        TableSchema schema = new TableSchema.Builder()
                .addKey("timestamp", ColumnValueType.INT64)
                .addKey("host", ColumnValueType.STRING)
                .addKey("rack", ColumnValueType.STRING)
                .addValue("utc_time", ColumnValueType.STRING)
                .addValue("data", ColumnValueType.STRING)
                .build();
        ExamplesUtil.runExample(client -> {
            ApiServiceTransactionOptions transactionOptions =
                    new ApiServiceTransactionOptions(ETransactionType.MASTER);
            try (ApiServiceTransaction transaction = client.startTransaction(transactionOptions).join()) {
                logger.info("Transaction started: {} (timestamp={}, ping={})",
                        transaction.getId(),
                        transaction.getStartTimestamp(),
                        transaction.isPing());

                transaction.ping().join();
                logger.info("Transaction ping succeeded!");

                ModifyRowsRequest request =
                        new ModifyRowsRequest("//home/dev/autorestart_nodes_copy", schema)
                                .addInsert(Arrays.asList(10, "myhost1", "myrack1", "utc_time1", "data1"))
                                .addInsert(Arrays.asList(11, "myhost2", "myrack2", "utc_time2", "data2"))
                                .addUpdate(new YTreeBuilder()
                                        .beginMap()
                                        .key("timestamp").value(1486190036109192L)
                                        .key("host").value("n0344-sas.cluster-name")
                                        .key("rack").value("SAS2.4.3-15")
                                        .key("data").value("XXX " + UUID.randomUUID().toString())
                                        .buildMap()
                                        .mapValue())
                                .addUpdate(new YTreeBuilder()
                                        .beginMap()
                                        .key("timestamp").value(1486190037953802L)
                                        .key("host").value("s03-sas.cluster-name")
                                        .key("rack").value("SAS2.4.3-15")
                                        .key("data").value("XXX " + UUID.randomUUID().toString())
                                        .buildMap()
                                        .mapValue());
                long t0 = System.nanoTime();
                transaction.modifyRows(request).join();
                long t1 = System.nanoTime();

                logger.info("Request time: {}ms", (t1 - t0) / 1000000.0);

                t0 = System.nanoTime();

    LookupRowsRequest lookup = new LookupRowsRequest("//home/dev/autorestart_nodes_copy", schema.toLookup())
                        .addFilter(1486190036109192L, "n0344-sas.cluster-name", "SAS2.4.3-15")
                        .addFilter(1486190037953802L, "s03-sas.cluster-name", "SAS2.4.3-15")
                        .addLookupColumns("timestamp", "data");


                t1 = System.nanoTime();
                UnversionedRowset rowset = client.lookupRows(lookup).join();
                long t2 = System.nanoTime();
                logger.info("Request time: {}ms + {}ms", (t1 - t0) / 1000000.0, (t2 - t1) / 1000000.0);
                logger.info("Result schema:");
                for (ColumnSchema column : rowset.getSchema().getColumns()) {
                    logger.info("    {}", column.getName());
                }
                for (UnversionedRow row : rowset.getRows()) {
                    logger.info("Row:");
                    for (UnversionedValue value : row.getValues()) {
                        logger.info("    value: {}", value);
                    }
                }
                for (YTreeMapNode row : rowset.getYTreeRows()) {
                    logger.info("Row: {}", row);
                }

                transaction.commit().join();
                logger.info("Transaction committed!");
            }
        });
    }
}

Для работы через Python необходимо установить пакет с биндингами, pypi-пакет называется ytsaurus-rpc-driver. После этого необходимо указать в качестве бэкенда rpc. Работа с динамическими таблицами: import yt.wrapper as yt

def main():
    client = yt.YtClient("cluster-name", config={"backend": "rpc"})
    schema = [
        {"name": "x", "type": "int64", "sort_order": "ascending"},
        {"name": "y", "type": "int64"},
        {"name": "z", "type": "int64"}
    ]

    table = "//home/ignat/dynamic_table"
    client.create("table", table, attributes={"schema": schema, "dynamic": True})
    client.mount_table(table, sync=True)
    client.insert_rows(table, [{"x": 0, "y": 99}])

    for iter in xrange(5):
        with client.Transaction(type="tablet"):
            rows = list(client.lookup_rows(table, [{"x": 0}]))
            if len(rows) == 1 and rows[0]["y"] <= 100:
                rows[0]["y"] += 1
                client.insert_rows(table, rows)

    print list(client.select_rows("* from [{}]".format(table)))

if __name__ == "__main__":
    main() Для того чтобы клиент ходил к проксям определённой роли (например, my_role), нужно указать в конфиге опцию proxy_role: client = yt.YtClient("cluster-name", config={"backend": "rpc", "driver_config": {"proxy_role": "my_role"}}) Мы также советуем включать дебажные логи клиентской библиотеки. Такие логи сильно помогут при возникновении проблем. Помимо обычного способа через переменную окружения YT_LOG_LEVEL=debug можно явно настроить логирование внутри rpc proxy client. Для этого нужно передать конфиг логирования через параметр driver_logging_config: logging_config = {
    'rules': [{'min_level': 'debug', 'writers': ['file']}],
    'writers': {'file': {'file_name': logging_file_name, 'type': 'file'}}
}
client = yt.YtClient("cluster-name", config={"backend": "rpc", "driver_logging_config": logging_config})

YTsaurus позволяет запустить Jupyter Notebooks на вычислительных мощностях кластера. Функциональность доступна только для кластеров, использующих CRI job environment. Для развёртывания ноутбука необходимо выполнить следующие действия: Установить переменную окружения JUPYT_CTL_ADDRESS в адрес strawberry controller для JUPYT. export JUPYT_CTL_ADDRESS=jupyt.test.yt.mycloud.net Выбрать docker-образ jupyter-ноутбука. В качестве образа или основы для образа можно выбрать jupyter stacks, например, minimal-notebook.


Создать ноутбук. Для создания ноутбука необходимо указать docker-образ с ноутбуком и пул, в котором будет запущена операция. yt jupyt ctl create --speclet-options '{jupyter_docker_image="quay.io/jupyter/minimal-notebook"; pool=my-pool}' test-jupyt Запустить ноутбук. yt jupyt ctl start test-jupyt Дождаться запуска ноутбука и получить ссылку на ноутбук. foo@bar:~$ yt jupyt ctl get-endpoint test-jupyt
{
    "address" = "http://some-node.yt.mycloud.net:27042";
    "operation_id" = "60b8ec86-6f123a7d-134403e8-ee6b88de";
    "job_id" = "16f76ac9-2a20ab96-13440384-14e";
} Внимание
Содержимое ноутбуков и файлы, созданные на файловой системе, теряются при перезапуске джоба с ноутбуком. Для надёжного хранения файлов необходимо использовать Кипарис.

При разработке библиотеки для работы с YTsaurus полезно понимать структуру выполнения команды. Каждая исполняемая команда представляет собой структуру, содержащую: информацию о пользователе, позволяющую провести аутентификацию (в случае работы по HTTP это чаще всего токен);
информацию о входном и выходном формате данных (представлена в виде YSON-строки с атрибутами);
информацию о параметрах команды (представлены в виде YSON-словаря);
входной (байтовый) поток данных;
выходной (байтовый) поток данных. Ниже приведены формальные спецификации кодирования каждого пункта в HTTP-прокси, которые включают в себя более широкую функциональность по интерпретации HTTP-запросов (отчасти для поддержки совместимости с такими HTTP-клиентами, как веб-браузер). Для корректной работы с YTsaurus требуется поддержать меньший набор функциональности, а именно: указывать X-YT-Header-Format, определяющий формат для заголовков X-YT-Input-Format, X-YT-Output-Format и X-YT-Parameters (значением заголовка является YSON);
указывать X-YT-Input-Format и X-YT-Output-Format, закодированные в соответствии с X-YT-Header-Format и определяющие форматы входных и выходных потоков данных;
все параметры команды передавать в заголовке X-YT-Parameters, закодированном в соответствии с X-YT-Header-Format;
все HTTP-ответы 5xx считать ошибкой транспортного уровня. Стоит отличать код 503, который является явным сигналом о временной недоступности, и код 500, сигнализирующий об ошибке на стороне YTsaurus. В первом случае можно повторить запрос;
во всех остальных ответах (2xx, 4xx) об успешном выполнении команды стоит судить по заголовкам/трейлерам X-YT-Error (предпочтительно) или X-YT-Response-Code (извлеченном из X-YT-Error коде ошибки) и X-YT-Response-Message (извлеченной из X-YT-Error диагностике ошибки).

Для выбора HTTP-метода для команды достаточно следовать следующему алгоритму: Если у команды есть поток входных данных, то PUT;
Если команда мутирующая, то POST;
Иначе GET.

Формат входных данных определяется по следующим правилам. Каждое последующее правило перекрывает предыдущее. Если указан заголовок Content-Type и указанный MIME-тип есть в таблице соответствия, то формат выбирается из таблицы;
Если указан заголовок X-YT-Input-Format, то содержимое заголовка интерпретируется как JSON-закодированная YSON-строка с атрибутами и она используется как описание входного формата;
Если ни п. 1, ни п. 2 не отработали успешно, то используется YSON.

Формат выходных данных определяется по следующим правилам. Каждое последующее правило перекрывает предыдущее. Если указан заголовок Accept, то выбирается лучший MIME-тип из таблицы, соответствующий Accept-заголовку, и далее формат берется из таблицы. Content-Type равен совпавшему MIME-типу;
Если указан заголовок X-YT-Output-Format, то содержимое заголовка интерпретируется как JSON-закодированная YSON-строка с атрибутами, и она используется как описание выходного формата. Content-Type равен application/octet-stream;
Если ни п. 1, ни п. 2 не отработали успешно, то используется Pretty YSON. Content-Type равен text/plain.

При использовании List и Dict, в аргументы функции передаются специальные read-only объекты yql.TList и yql.TDict. Их особенности: Read-only: в них нельзя что-то поменять не скопировав, так как тем же объектом может пользоваться какая-то другая часть текущего запроса, например соседняя функция.
Ценой потенциально медленного копирования можно получить из них настоящий объект типа list, проитерировавшись для частичного копирования. Для словарей нужно дополнительно вызвать iteritems(). Установив значение атрибута _yql_lazy_input в False на самой функции можно включить автоматическое копирование списков и словарей в list и dict. Данный механизм работает рекурсивно для вложенных контейнеров.
Для получения количества элементов можно вызвать len(my_arg).
Актуальный набор доступных методов можно узнать с помощью вызова dir(my_arg). Пример. Методы yql.TList: has_fast_len() — можно ли быстро получить длину. Если вернулось False, то список "ленивый".
has_items() — проверка на пустоту.
reversed() — получить перевернутую копию списка.
skip(n) и take(n) — аналоги срезов [n:] и [:n], соответственно.
to_index_dict() - получить словарь с номерами элементов в качестве ключей, что позволяет осуществлять доступ по индексу. Пример с _yql_lazy_input: $u = SystemPython3_8::list_func(Callable<(List<Int32>)->Int32>, @@#py
def list_func(lst):
  return lst.count(1)
list_func._yql_lazy_input = False
@@);
SELECT $u(AsList(1,2,3));

SystemPython UDF будет вызываться в отдельной операции в рамках пользовательского скрипта. Взаимодействие с Python происходит через динамическую библиотеку libpython3.N.so, линковка с которой происходит во время исполнения. Подмена этой библиотеки в окружении приведёт к изменению используемого Python и доступных библиотек. Изменение окружения из YQL операции возможно при помощи прагм yt.DockerImage и yt.LayerPaths. Они повлияют на соответствующие параметры пользовательского скрипта, описание которых можно посмотреть в разделе Настройки операций - Параметры пользовательского скрипта. Окружение по умолчанию
По умолчанию используется дефолтное окружение для джобов, настраиваемое администратором кластера. Оно может не содержать Python требуемой версии. Пример использования библиотеки tensorflow с помощью pragma yt.DockerImage: pragma yt.DockerImage = "docker.io/tensorflow/tensorflow:2.16.1";

$script = @@#py
import sys
import tensorflow

def foo():
    return "Python version: " + sys.version + ".\nTensorflow version: " + tensorflow.__version__
@@;

$udf = SystemPython3_11::foo(Callable<()->String>, $script);
SELECT $udf();
-- Python version: 3.11.0rc1 (main, Aug 12 2022, 10:02:14) [GCC 11.2.0].
-- Tensorflow version: 2.16.1

$script = @@#py
def hello(name):
    return b'Hello, %s!' % name
@@;

$udf = SystemPython3_8::hello(Callable<(String)->String>, $script);

SELECT $udf("world"); -- "Hello, world!"

$script = @@#py
def concat(a, b):
    return a.decode("utf-8") + str(b)
@@;
$concat = SystemPython3_8::concat(Callable<(String?, Int64?)->String>, $script);

SELECT $concat(name, age) FROM `//tmp/sample`;

$u = SystemPython3_8::get_dir(Callable<(List<Int32>)->List<String>>, @@#py
def get_dir(lst):
  return dir(lst)
@@);
SELECT $u(AsList());

Необходимо правильное окружение, которое может быть получено с помощью следующего Dockerfile: FROM ollama/ollama:0.3.9
RUN apt install -y python3.11 libpython3.11 python3-pip
RUN python3.11 -m pip install ollama Используя указанный образ, можно вызывать Llama из Python: pragma yt.DockerImage = "my.docker.registry/ollama/ollama:0.3.9-with-python3.11-2";
pragma yt.DefaultMemoryLimit = "30G";
pragma yt.OperationSpec = "{max_failed_job_count=1;mapper={cpu_limit=64}}";

$script = @@#py
from ollama import Client
import subprocess

def infer_llama(prompt):
    proc = subprocess.Popen(["/bin/ollama", "serve"], stdout=subprocess.DEVNULL)
    client = Client(host='http://localhost:11434')
    client.pull('llama3.1')
    response = client.chat(model='llama3.1', messages=[
        {
            'role': 'user',
            'content': str(prompt),
        },
    ])
    proc.kill()
    return response['message']['content']
@@;
$infer_llama = SystemPython3_11::infer_llama(Callable<(String?)->String>, $script);

select $infer_llama("Why is the sky blue?");

